import * as T from './vendor/three.module.js';
import {obstacleFromMesh,segmentObstacleClearance,routeClearance} from './routing-audit.js';

const overlaps=(a,b,gap=0)=>a.min.every((v,k)=>v<=b.max[k]+gap&&a.max[k]+gap>=b.min[k]);
const boundsOf=o=>o.bounds||{min:o.min,max:o.max};
const descendant=(node,parent)=>{for(let p=node;p;p=p.parent)if(p===parent)return true;return false;};
const ownerOf=(node,key)=>{for(let p=node;p;p=p.parent)if(p.userData?.[key])return p.userData[key];return null;};
function edgesFromBounds(bounds){const vertices=[];for(const x of[0,1])for(const y of[0,1])for(const z of[0,1])vertices.push([x?bounds.max[0]:bounds.min[0],y?bounds.max[1]:bounds.min[1],z?bounds.max[2]:bounds.min[2]]);const edges=[];for(let i=0;i<8;i++)for(const bit of[1,2,4])if(!(i&bit))edges.push([vertices[i],vertices[i|bit]]);return edges;}
function meshEdges(mesh,frame){const geometry=mesh.geometry,p=geometry.attributes.position,index=geometry.index,matrix=frame.matrixWorld.clone().invert().multiply(mesh.matrixWorld),vertices=Array.from({length:p.count},(_,i)=>new T.Vector3(p.getX(i),p.getY(i),p.getZ(i)).applyMatrix4(matrix).toArray()),edges=[],seen=new Set();for(let i=0,n=index?.count??p.count;i+2<n;i+=3){const triangle=[0,1,2].map(k=>index?index.getX(i+k):i+k);for(let j=0;j<3;j++){const a=vertices[triangle[j]],b=vertices[triangle[(j+1)%3]],key=[a.join(','),b.join(',')].sort().join('|');if(seen.has(key))continue;seen.add(key);edges.push([a,b]);}}return edges;}

/** Exact actual-mesh interference and conservative complete plug strokes.
 * Coordinates are body metres. A bank's own enclosure, receptacles and
 * explicitly named rigid busbar junction form one designed assembly; every
 * other physical object remains in this check and in the route registry.
 */
function inspectElectricalAssemblyHardware({root,architecture,actualBoxes,physicalMeshes,lines,obstacles,terminalVolumes,world,normal,allocations=architecture.collectorAccommodations||[],ownerProperty='fixedCollectorBoxId',issuePrefix='fixed-collector',scope='Fixed collector bank mechanical accommodation and complete connector strokes. Full circuits and continuous spacecraft motion remain independently required.'},{hardwareClearanceM=0,cableClearanceM=.002,maxIssues=40}={}){
 if(!root||![hardwareClearanceM,cableClearanceM].every(x=>Number.isFinite(x)&&x>=0)||!Number.isInteger(maxIssues)||maxIssues<0)throw new Error('Invalid electrical assembly hardware inspection');
 root.updateWorldMatrix(true,true);const byId=new Map(physicalMeshes.map(m=>[m.uuid,m])),edgeCache=new Map(),solidCache=new Map(),rows=[],issues=[];let issueCount=0;
 const solid=node=>{if(!solidCache.has(node))solidCache.set(node,obstacleFromMesh(node,{frame:root}));return solidCache.get(node);},edges=node=>{if(!edgeCache.has(node))edgeCache.set(node,meshEdges(node,root));return edgeCache.get(node);};
 const material=obstacles.map(o=>{const node=byId.get(o.sourceMesh||o.id);if(node)return {obstacle:solid(node),node};const b=boundsOf(o);return {obstacle:{id:o.id,type:'box',min:b.min,max:b.max,bounds:b},node:null,conservativeEnvelope:true};});
 function touches(a,aEdges,b,bEdges){if(!overlaps(boundsOf(a),boundsOf(b),hardwareClearanceM))return false;for(const [p,q]of aEdges)if(segmentObstacleClearance(p,q,b,{clearanceM:hardwareClearanceM})<=1e-9)return true;for(const [p,q]of bEdges)if(segmentObstacleClearance(p,q,a,{clearanceM:hardwareClearanceM})<=1e-9)return true;return false;}
 for(const allocation of allocations){
  const host=actualBoxes.get(allocation.boxId)?.root,row={boxId:allocation.boxId,ok:false,issues:[],issueCount:0,actualMeshes:0,assemblyChecks:0,sweepChecks:0,straightApproaches:0,intentionalAssemblyJoins:[],allocationBasis:allocation.basis,massStationBasis:allocation.massStationBasis,basis:'Actual rendered material against every other installed physical object. The complete plug translation is enclosed conservatively before comparison. Only explicitly identified members of this same allocated assembly may touch one another; they remain physical obstacles for every routed circuit.'};
  const issue=(code,detail={})=>{const value={code:code.replace('fixed-collector',issuePrefix),boxId:allocation.boxId,...detail};row.issueCount++;issueCount++;if(row.issues.length<maxIssues)row.issues.push(value);if(issues.length<maxIssues)issues.push(value);};
  if(!host){issue('missing-fixed-collector-hardware');rows.push(row);continue;}
  const actualPositionM=root.worldToLocal(host.getWorldPosition(new T.Vector3())).toArray();row.actualPositionM=actualPositionM;row.declaredPositionM=allocation.positionM;
  if(!allocation.positionM?.every(Number.isFinite)||Math.hypot(...actualPositionM.map((x,k)=>x-allocation.positionM[k]))>1e-7)issue('fixed-collector-datum-mismatch',{actualPositionM,declaredPositionM:allocation.positionM});
  const own=physicalMeshes.filter(node=>descendant(node,host)),joined=new Set(physicalMeshes.filter(node=>ownerOf(node,ownerProperty)===allocation.boxId));row.actualMeshes=own.length;if(!own.length)issue('missing-fixed-collector-material');row.intentionalAssemblyJoins=[...joined].filter(node=>!descendant(node,host)).map(node=>({id:node.uuid,name:node.name}));
  const external=material.filter(({node})=>!node||(!descendant(node,host)&&!joined.has(node)));
  for(const mesh of own){const ownSolid=solid(mesh),ownEdges=edges(mesh);for(const other of external){if(!overlaps(ownSolid.bounds,boundsOf(other.obstacle),hardwareClearanceM))continue;row.assemblyChecks++;if(touches(ownSolid,ownEdges,other.obstacle,other.node?edges(other.node):edgesFromBounds(boundsOf(other.obstacle))))issue(other.conservativeEnvelope?'fixed-collector-operating-envelope-overlap':'fixed-collector-hardware-interference',{sourceMeshId:mesh.uuid,sourceName:mesh.name,obstacleId:other.obstacle.id,obstacleName:other.node?.name||other.obstacle.id,obstaclePart:other.node?.userData?.part,obstacleMaterialRole:other.node?.userData?.materialRole,obstacleParents:other.node?[other.node.parent?.name,other.node.parent?.parent?.name]:[],obstacleBounds:boundsOf(other.obstacle)});}}
  const bankLines=lines.filter(line=>[line.r.spec.fromBoxId,line.r.spec.toBoxId].includes(allocation.boxId));if(!Number.isInteger(allocation.physicalConnectorCount)||bankLines.length!==allocation.physicalConnectorCount)issue('fixed-collector-circuit-inventory-mismatch',{expected:allocation.physicalConnectorCount,actual:bankLines.length});
  for(const line of bankLines){const end=line.r.spec.fromBoxId===allocation.boxId?'from':'to',port=line.r[end],mate=port?.mates?.find(m=>m.male===line[end]?.parent),sweep=terminalVolumes.find(o=>o.id===line.id+':'+line.r.spec[end+'PortId']+':backshell-service-sweep');if(!sweep||!mate||![mate.male,mate.female].every(group=>physicalMeshes.some(node=>descendant(node,group)))){issue('missing-fixed-collector-withdrawal-envelope',{routeId:line.id});continue;}const sweepEdges=edgesFromBounds(boundsOf(sweep)),strokeObstacles=material.filter(({node})=>!node||(!descendant(node,mate.male)&&!descendant(node,mate.female)));for(const other of strokeObstacles){if(!overlaps(boundsOf(sweep),boundsOf(other.obstacle),hardwareClearanceM))continue;row.sweepChecks++;if(touches(sweep,sweepEdges,other.obstacle,other.node?edges(other.node):edgesFromBounds(boundsOf(other.obstacle))))issue('fixed-collector-withdrawal-interference',{routeId:sweep.lineId,sweepId:sweep.id,obstacleId:other.obstacle.id,obstacleName:other.node?.name||other.obstacle.id,obstaclePart:other.node?.userData?.part,obstacleMaterialRole:other.node?.userData?.materialRole,obstacleParents:other.node?[other.node.parent?.name,other.node.parent?.parent?.name]:[],obstacleBounds:boundsOf(other.obstacle)});}}
  for(const line of bankLines){const end=line.r.spec.fromBoxId===allocation.boxId?'from':'to',a=world(line[end]),n=normal(line[end]),b=a.map((v,k)=>v+n[k]*(line.bendRadiusM*2.4+.015)),screen=routeClearance({id:line.id,points:[a,b],radiusM:line.radiusM,clearanceM:cableClearanceM},[...obstacles,...terminalVolumes.filter(o=>o.lineId!==line.id)]);row.straightApproaches++;if(!screen.ok)issue('fixed-collector-approach-interference',{routeId:line.id,...screen});}
  row.ok=row.issueCount===0;rows.push(row);
 }
 return {ok:issueCount===0,issueCount,issues,rows,scope};
}

export function inspectFixedCollectorHardware(args,options){return inspectElectricalAssemblyHardware(args,options);}

export function inspectInstalledEquipmentHardware(args,options){
 const allocations=args.architecture.boxes.filter(box=>box.routingAccommodation).map(box=>({...box.routingAccommodation,boxId:box.id,positionM:box.positionM,physicalConnectorCount:args.architecture.harnesses.filter(h=>[h.fromBoxId,h.toBoxId].includes(box.id)).reduce((n,h)=>n+h.quantity*h.connectorPairsPerAssembly,0)}));
 return inspectElectricalAssemblyHardware({...args,allocations,ownerProperty:'electricalBoxId',issuePrefix:'equipment',scope:'Declared equipment accommodation: actual enclosure/panel/connector material, complete plug strokes, circuit inventory and full straight approaches against every other installed physical object. Circuit routing and continuous motion remain independent required checks.'},options);
}
